<script setup lang="ts">
import {ref,watch} from 'vue'
import {Plus,Trash2,ArrowUp,ArrowDown,Globe2,Upload,Save,LoaderCircle} from 'lucide-vue-next'
import {api,notify,type Row} from '../lib'
const props=defineProps<{value:Row}>(),emit=defineEmits<{saved:[]}>()
const items=ref<Row[]>([]),busy=ref(false),error=ref(''),uploading=ref(false)
watch(()=>props.value,value=>{items.value=JSON.parse(JSON.stringify(value.items||[]))},{immediate:true})
function add(){items.value.push({id:crypto.randomUUID(),label:'',url:'',visibility:'user',icon_svg:'',enabled:true,open_new_tab:false,hide_open_button:false})}
function move(index:number,step:number){const target=index+step;if(target<0||target>=items.value.length)return;[items.value[index],items.value[target]]=[items.value[target],items.value[index]]}
async function upload(item:Row,event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;error.value='';uploading.value=true
 try{if(file.size>20000)throw new Error('SVG 图标不能超过 20 KB');const text=await file.text();if(!/^\s*(?:<\?xml[^>]*>\s*)?<svg[\s>]/i.test(text))throw new Error('请选择 SVG 图标文件');item.icon_svg=text}catch(e){error.value=(e as Error).message}finally{input.value='';uploading.value=false}
}
async function save(){busy.value=true;error.value='';try{await api('/admin/settings/custom_menus','PUT',{items:items.value});notify('自定义菜单已保存');emit('saved')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const icon=(svg:string)=>'data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg)
</script>
<template><section class="menu-editor"><h2>自定义菜单</h2><p class="muted small">添加页面到侧边栏，按角色展示。选择新窗口打开，或在工作台内直接查看。</p><p v-if="error" class="alert danger" role="alert">{{error}}</p>
 <form @submit.prevent="save"><fieldset :disabled="busy||uploading"><p v-if="!items.length" class="empty">还没有自定义菜单，点击下方按钮添加。</p>
  <article v-for="(item,index) in items" :key="item.id" class="menu-card"><div class="menu-heading"><b>菜单 {{index+1}}<span v-if="item.label"> · {{item.label}}</span></b><div><button type="button" class="icon-btn" :disabled="index===0" :aria-label="'上移菜单 '+(index+1)" @click="move(index,-1)"><ArrowUp :size="16"/></button><button type="button" class="icon-btn" :disabled="index===items.length-1" :aria-label="'下移菜单 '+(index+1)" @click="move(index,1)"><ArrowDown :size="16"/></button><button type="button" class="icon-btn delete-menu" :aria-label="'删除菜单 '+(index+1)" @click="items.splice(index,1)"><Trash2 :size="16"/></button></div></div>
   <div class="form-grid"><label>菜单名称<input v-model.trim="item.label" required maxlength="60" placeholder="例如：充值中心"/></label><label>可见角色<select v-model="item.visibility"><option value="user">普通用户</option><option value="admin">管理员</option><option value="all">所有登录用户</option></select></label><label class="span2">页面 URL<input v-model.trim="item.url" type="url" required maxlength="2048" placeholder="https://example.com/page"/></label></div>
   <div class="menu-options"><label class="checkbox-label"><input type="checkbox" v-model="item.enabled"/>启用菜单</label><label class="checkbox-label"><input type="checkbox" v-model="item.open_new_tab"/>新窗口打开</label><label v-if="!item.open_new_tab" class="checkbox-label"><input type="checkbox" v-model="item.hide_open_button"/>隐藏页面中的“新窗口打开”按钮</label></div>
   <div class="icon-editor"><span>SVG 图标</span><div><span class="icon-preview"><img v-if="item.icon_svg" :src="icon(item.icon_svg)" alt="菜单图标预览"/><Globe2 v-else :size="22"/></span><label class="btn secondary upload-label"><Upload :size="15"/>上传 SVG<input type="file" accept=".svg,image/svg+xml" @change="upload(item,$event)"/></label><button v-if="item.icon_svg" type="button" class="btn secondary" @click="item.icon_svg=''"><Trash2 :size="15"/>清除</button></div><small class="muted">支持 20 KB 以内的静态 SVG，留空使用默认图标。</small></div>
  </article>
  <button type="button" class="btn secondary" :disabled="items.length>=30" @click="add"><Plus :size="16"/>添加菜单</button><p class="muted small menu-note">最多 30 个，按列表顺序显示。站内打开需要目标网站允许嵌入；不能嵌入的页面请选择“新窗口打开”。</p>
 </fieldset><div class="form-footer"><button class="btn primary" :disabled="busy||uploading"><LoaderCircle v-if="busy" class="spinning" :size="16"/><Save v-else :size="16"/>{{busy?'保存中…':'保存配置'}}</button></div></form>
</section></template>
<style scoped>.menu-editor h2{margin:0 0 8px}.menu-editor fieldset{border:0;padding:0;margin:24px 0 0;min-width:0}.menu-card{border:1px solid var(--line);border-radius:12px;padding:20px;margin-bottom:18px}.menu-heading{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:18px}.menu-heading b{font-size:13px;overflow-wrap:anywhere}.menu-heading>div{display:flex;flex-shrink:0}.delete-menu{color:#c75252}.menu-options{display:flex;flex-wrap:wrap;gap:14px 24px;margin:18px 0}.menu-options label{margin:0;font-size:12px}.icon-editor>span{font-size:12px}.icon-editor>div{display:flex;align-items:center;gap:10px;margin:10px 0}.icon-preview{width:46px;height:46px;border:1px dashed var(--line);border-radius:10px;display:grid;place-items:center;color:var(--muted)}.icon-preview img{width:25px;height:25px;object-fit:contain}.upload-label{position:relative;cursor:pointer;margin:0;font-weight:500}.upload-label input{position:absolute;inset:0;opacity:0;cursor:pointer;width:100%;margin:0}.menu-note{line-height:1.8}.menu-editor .form-footer{margin-top:20px}@media(max-width:600px){.menu-card{padding:14px}.menu-heading b span{display:none}.menu-options{flex-direction:column}.icon-editor .btn{padding:8px 10px}}</style>
